package com.pulsepay.webhook;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import javax.crypto.*; import javax.crypto.spec.GCMParameterSpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class SecretCrypto { private final byte[] key; public SecretCrypto(@Value("${pulsepay.webhook-encryption-key:${WEBHOOK_ENCRYPTION_KEY:change-me-development-key-32-bytes}}")String raw){try{key=MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8));}catch(Exception e){throw new IllegalStateException(e);}} public String encrypt(String s){try{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,new javax.crypto.spec.SecretKeySpec(key,"AES"),new GCMParameterSpec(128,iv));return Base64.getEncoder().encodeToString(iv)+":"+Base64.getEncoder().encodeToString(c.doFinal(s.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} public String decrypt(String s){try{String[] p=s.split(":");Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,new javax.crypto.spec.SecretKeySpec(key,"AES"),new GCMParameterSpec(128,Base64.getDecoder().decode(p[0])));return new String(c.doFinal(Base64.getDecoder().decode(p[1])),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException(e);}} }
